import AppKit

/// The character, loaded as data rather than reimplemented.
///
/// Every frame Wity can be in is generated by the Python module and baked into
/// the bundle at build time. Drawing code here, art there: one source of truth,
/// for the same reason the page's headline is derived from the mood rather than
/// ranked a second time.
public struct Mascot: Decodable {
    /// One character in the cast. Everything that makes it *that* character
    /// lives in the art; this is only what a picker needs to name it.
    public struct Figure: Decodable, Identifiable, Hashable {
        public let id: String
        public let name: String
        /// Which part of it always takes the status colour. A figure whose
        /// eyes are dark would otherwise lose the tint entirely at 22 pixels
        /// and stop being an instrument — so every one declares a tell, and
        /// the picker says what it is.
        public let tell: String
    }

    public let width: Int
    public let height: Int
    public let frames: Int
    public let slots: [String: String]
    public let skins: [String: [String: String]]
    public let defaultSkin: String
    public let sprites: [String: [String]]
    public let walkSprites: [String: [String]]?
    public let figures: [Figure]
    public struct Companion: Decodable {
        public let width: Int
        public let height: Int
        public let sprites: [String: [String]]
        public let walkingSprites: [String: [String]]?
        public let walkingFrames: Int?
        public let palettes: [String: [String: String]]
        /// Where each character holds the disk balloon's string, per frame,
        /// in the grid of the art that pose is drawn from.
        public let hands: [String: Hands]?
        private enum CodingKeys: String, CodingKey {
            case width, height, sprites, palettes, hands
            case walkingSprites = "walking_sprites"
            case walkingFrames = "walking_frames"
        }
    }
    public struct Hands: Decodable {
        public let front: [[Int]]
        public let walk: [[Int]]
    }
    public let companion: Companion?
    public let menu: Companion?
    public let defaultFigure: String

    public enum CodingKeys: String, CodingKey {
        case width, height, frames, slots, skins, sprites, figures, companion, menu
        case walkSprites = "walk_sprites"
        case defaultSkin = "default_skin"
        case defaultFigure = "default_figure"
    }

    public static func load(_ url: URL) -> Mascot? {
        guard let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(Mascot.self, from: data)
    }

    /// Falls back to the default figure, because a saved preference outlives
    /// the character it names: a cast member renamed between releases would
    /// otherwise leave the app with no face and no explanation.
    ///
    /// The fallback is on the whole key, not on the figure id. Testing
    /// `sprites[figure]` looks right and is always nil — the dictionary is
    /// keyed by the composed `figure/gauge/eyes/frame`, so every figure took
    /// the fallback and the entire cast rendered as the cat.
    public func rows(figure: String, gauge: Int, eyes: String, frame: Int) -> [String]? {
        let f = frame % max(frames, 1)
        return sprites["\(figure)/\(gauge)/\(eyes)/\(f)"]
            ?? sprites["\(defaultFigure)/\(gauge)/\(eyes)/\(f)"]
    }

    public func has(figure: String) -> Bool {
        figures.contains { $0.id == figure }
    }

    /// Where the character holds the balloon's string, in the points of an
    /// image `image(...)` drew for the same pose, origin bottom-left.
    ///
    /// Per frame, because hands swing: a fixed point is where the hand was,
    /// and the string would start in mid-air while the arm moves away from it.
    public func hand(figure: String, frame: Int, walking: Bool, facesLeft: Bool,
                     imageSize: NSSize) -> NSPoint? {
        guard let hands = companion?.hands?[figure] else { return nil }
        let list = walking ? hands.walk : hands.front
        guard !list.isEmpty else { return nil }
        let p = list[((frame % list.count) + list.count) % list.count]
        guard p.count == 2 else { return nil }
        // The grid of the art this pose is drawn from: detailed companion art,
        // or Wity and Nipper's original portraits.
        let art = walking ? companion?.walkingSprites?["\(figure)/open/0"]
                          : companion?.sprites["\(figure)/open/0"]
        let gridW = art?.first?.count ?? width, gridH = art?.count ?? height
        let scale = imageSize.height / CGFloat(gridH)
        var x = (CGFloat(p[0]) + 0.5) * scale
        if facesLeft { x = CGFloat(gridW) * scale - x }
        return NSPoint(x: x, y: (CGFloat(gridH - 1 - p[1]) + 0.5) * scale)
    }
}

public enum Ink {
    /// `#rrggbb` as written by the Python palette. Anything unparseable returns
    /// nil so a bad colour shows as a hole rather than silently as black — a
    /// missing pixel is noticed, a black one is not.
    public static func color(_ hex: String) -> NSColor? {
        var s = hex
        if s.hasPrefix("#") { s.removeFirst() }
        guard s.count == 6, let v = UInt32(s, radix: 16) else { return nil }
        return NSColor(srgbRed: CGFloat((v >> 16) & 0xff) / 255,
                       green: CGFloat((v >> 8) & 0xff) / 255,
                       blue: CGFloat(v & 0xff) / 255, alpha: 1)
    }
}

extension Mascot {
    /// The coat each character was drawn in. The picker previews a character
    /// in it and choosing the character puts it on, so every surface has to
    /// agree — which is why there is one table. It was copied into five views,
    /// and adding a character meant finding all five.
    public static let drawnCoats: [String: String] = [
        "robot": "graphite", "rooster": "sunrise", "rabbit": "chestnut", "snowman": "frost",
        "palm": "tropical", "orb": "pearl", "antenna": "cherry", "pup": "snow", "rex": "moss",
    ]

    /// Frames already drawn. The clock asks for a frame about four times a
    /// second in up to three places (window, floating companion, menu bar),
    /// and a pose repeats every few seconds: drawing it pixel by pixel each
    /// time was half a millisecond of work for a picture already made. Keyed
    /// by the sprite actually chosen, not the frame asked for, because the
    /// clock's frame counts up forever while the art loops.
    private static let drawn: NSCache<NSString, NSImage> = {
        let c = NSCache<NSString, NSImage>()
        // Every pose of one character in one coat, at the three sizes it is
        // drawn at, with room for a coat change.
        c.countLimit = 600
        return c
    }()

    /// One frame as an image, sized to fit `height` points.
    ///
    /// Drawn at an integral pixel scale and never interpolated: a pixel
    /// character resampled to a fractional size stops being pixel art and
    /// becomes a smudge, which is exactly what it looks like when it goes wrong.
    /// The image is shared from a cache: callers must not mutate it.
    public func image(figure: String, gauge: Int, eyes: String, frame: Int, skin: String,
               tint: String, fitting height: CGFloat, mood: String? = nil, detailed: Bool = false,
               showSignal: Bool = true, walking: Bool = false, facesLeft: Bool = false) -> NSImage? {
        let dedicatedArt = detailed ? companion : (!showSignal ? menu : nil)
        if let art = dedicatedArt {
            let walkKey = "\(figure)/\(eyes)/\(frame % max(art.walkingFrames ?? frames, 1))"
            let standKey = "\(figure)/\(eyes)/\(frame % max(frames, 1))"
            let walkRows = walking ? art.walkingSprites?[walkKey] : nil
            if let rows = walkRows ?? art.sprites[standKey],
               let palette = art.palettes["\(figure)/\(skin)"] ?? art.palettes["\(figure)/\(defaultSkin)"] {
                let key = [detailed ? "companion" : "menu", walkRows == nil ? "stand" : "walk",
                           walkRows == nil ? standKey : walkKey, skin, tint, mood ?? "-",
                           "\(height)", "\(showSignal)", "\(facesLeft)"].joined(separator: "|")
                return Self.cached(key) {
                    drawDedicated(rows: rows, palette: palette, width: art.width, tint: tint,
                                  fitting: height, mood: mood, showSignal: showSignal, facesLeft: facesLeft)
                }
            }
        }
        let f = frame % max(frames, 1)
        let companionWalkKey = "\(figure)/\(eyes)/\(f)"
        let walkKey = "\(figure)/\(gauge)/\(eyes)/\(f)"
        let companionWalk = walking ? companion?.walkingSprites?[companionWalkKey] : nil
        let plainWalk = walking && companionWalk == nil ? walkSprites?[walkKey] : nil
        let source: String
        let found: [String]?
        if let companionWalk {
            source = "cwalk|" + companionWalkKey; found = companionWalk
        } else if let plainWalk {
            source = "walk|" + walkKey; found = plainWalk
        } else {
            // `rows` falls back to the default figure; the key must name what
            // was drawn, or two figures could share one picture.
            let own = sprites["\(figure)/\(gauge)/\(eyes)/\(f)"] != nil
            source = "stand|" + (own ? figure : defaultFigure) + "/\(gauge)/\(eyes)/\(f)"
            found = rows(figure: figure, gauge: gauge, eyes: eyes, frame: frame)
        }
        guard let rows = found else { return nil }
        let key = [source, skin, tint, mood ?? "-", "\(height)", "\(showSignal)", "\(facesLeft)"]
            .joined(separator: "|")
        return Self.cached(key) {
            drawPlain(rows: rows, skin: skin, tint: tint, fitting: height, mood: mood,
                      showSignal: showSignal, facesLeft: facesLeft)
        }
    }

    private static func cached(_ key: String, draw: () -> NSImage) -> NSImage {
        if let hit = drawn.object(forKey: key as NSString) { return hit }
        let image = draw()
        drawn.setObject(image, forKey: key as NSString)
        return image
    }

    /// Detailed companion or menu art: drawn whole, never cropped or
    /// fractionally resampled.
    private func drawDedicated(rows: [String], palette: [String: String], width artWidth: Int,
                               tint: String, fitting height: CGFloat, mood: String?,
                               showSignal: Bool, facesLeft: Bool) -> NSImage {
        let rowHeight = rows.count
        let rowWidth = rows.first?.count ?? artWidth
        let scale = max(1, floor(height / CGFloat(rowHeight)))
        let size = NSSize(width: CGFloat(rowWidth) * scale, height: CGFloat(rowHeight) * scale)
        // One parse per colour, not one per pixel.
        var inks: [Character: NSColor] = [:]
        for (k, hex) in palette { if let ch = k.first, let c = Ink.color(hex) { inks[ch] = c } }
        let image = NSImage(size: size)
        image.lockFocus()
        NSGraphicsContext.current?.imageInterpolation = .none
        let context = NSGraphicsContext.current?.cgContext
        context?.saveGState()
        if facesLeft {
            context?.translateBy(x: size.width, y: 0)
            context?.scaleBy(x: -1, y: 1)
        }
        for (y, row) in rows.enumerated() {
            for (x, ch) in row.enumerated() where ch != "." {
                guard let color = inks[ch] else { continue }
                color.setFill()
                NSRect(x: CGFloat(x)*scale, y: CGFloat(rowHeight-1-y)*scale,
                       width: scale, height: scale).fill()
            }
        }
        context?.restoreGState()
        if let mood, showSignal {
            // Keep the badge at menu-bar size so art stays the focus.
            MascotSignal.draw(mood: mood, tint: tint, at: NSPoint(x: size.width-9, y: 0), scale: 1)
        }
        image.unlockFocus()
        return image
    }

    private func drawPlain(rows: [String], skin: String, tint: String, fitting height: CGFloat,
                           mood: String?, showSignal: Bool, facesLeft: Bool) -> NSImage {
        let palette = skins[skin] ?? skins[defaultSkin] ?? [:]
        let accent = Ink.color(tint) ?? .systemGreen
        var inks: [Character: NSColor] = [:]
        for (ch, slot) in slots {
            guard let c = ch.first else { continue }
            let color = slot == "accent"
                ? (mood == nil ? accent : Ink.color(palette["pale"] ?? ""))
                : Ink.color(palette[slot] ?? "")
            if let color { inks[c] = color }
        }

        // Integral scale, then crop to fit rather than shrink to fit. The menu
        // bar is 22pt and the character is 23 rows, so "scale to fit" would
        // resample by 22/23 and turn pixel art into a smudge. Losing the bottom
        // row of outline is invisible; a fractional scale is not.
        let scale = max(1, floor(height / CGFloat(self.height)))
        let maxRows = max(1, Int(floor(height / scale)))
        let drawnRows = min(self.height, maxRows)
        let size = NSSize(width: CGFloat(width) * scale, height: CGFloat(drawnRows) * scale)
        let image = NSImage(size: size)
        image.lockFocus()
        NSGraphicsContext.current?.imageInterpolation = .none
        let context = NSGraphicsContext.current?.cgContext
        context?.saveGState()
        if facesLeft {
            context?.translateBy(x: size.width, y: 0)
            context?.scaleBy(x: -1, y: 1)
        }
        for (y, row) in rows.enumerated() where y < drawnRows {
            for (x, ch) in row.enumerated() where ch != "." {
                guard let color = inks[ch] else { continue }
                color.setFill()
                // Sprite rows run top-down; AppKit's origin is bottom-left.
                NSRect(x: CGFloat(x) * scale,
                       y: CGFloat(drawnRows - 1 - y) * scale,
                       width: scale, height: scale).fill()
            }
        }
        context?.restoreGState()
        if let mood, showSignal {
            MascotSignal.draw(mood: mood, tint: tint, at: NSPoint(x: size.width - 9, y: 0), scale: 1)
        }
        image.unlockFocus()
        return image
    }
}
